 public static Integer BinarySearch(Integer DataToFind){
        Integer MidValue = 0;
        Integer First = 0;
        Integer Last = NumberItems;
        while (First <= Last){
              MidValue = (First + Last) / 2;
              if(DataToFind == DataStored[MidValue]){
                     return MidValue;
              }
              if(DataToFind < DataStored[MidValue]){
                     Last = MidValue - 1;
              }else{
                     First = MidValue + 1;
              }
        }
        return -1;
 }
